import math

def valid_triangle(a,b,c):
    return a+b>c and a+c>b and b+c>a

def compute_q(ab,ac,bc,cd,bf):
    # Preconditions: 1<=cd<=bc-1, 1<=bf<=bc-1
    bd = bc - cd
    cf = bc - bf
    if bd == 0 or bf == 0:
        return None
    # r = (ab/ac)^2 as reduced fraction
    num_r = ab*ab
    den_r = ac*ac
    g = math.gcd(num_r, den_r)
    num_r //= g
    den_r //= g
    # t1 = r * cd/bd = n1/d1
    n1 = num_r * cd
    d1 = den_r * bd
    g1 = math.gcd(n1, d1)
    n1 //= g1
    d1 //= g1
    # t2 = r * cf/bf = n2/d2
    n2 = num_r * cf
    d2 = den_r * bf
    g2 = math.gcd(n2, d2)
    n2 //= g2
    d2 //= g2
    # Ratio R = [n1*(d2+n2)]/[n2*(d1+n1)]
    N = n1 * (d2 + n2)
    D = n2 * (d1 + n1)
    if N == 0 or D == 0:
        return None
    g3 = math.gcd(N, D)
    N //= g3
    D //= g3
    # D is the denominator q
    return D

